function grid$m38Distribute2(f){
  this.constructor(f);
}
grid$m38Distribute2.prototype = new DirEvent();
grid$m38Distribute2.prototype.beforeInit = function(renderType){
  var p = this._dir;
}
grid$m38Distribute2.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid();

  var exp = {
    cl_nt: ['*cl_nt', '[t_tt_nt] - [da_pb_nt] - [tt_nt]']
  }
  p.applyExpression(exp, g, false);
  g.FomulaApplied = {"tt_nt": ["cl_nt"]}

  this.refreshSub();
}
grid$m38Distribute2.prototype.beforeButtonGridClick = function (id, gindex, r) {
  var p = this._dir, g = p.grid(), time = $.userinfo.val('ProcessTimeout');
  switch (id) {
    case 'save':
      var m = new Memvars(), dsave = g.data.clone(['id', 'so_ct', 'ngay_ct', 'ma_unit', 'ma_nt', 'tt_nt'], '[tt_nt] > 0');
      if (dsave.count() == 0) {$.showToast('$NoRowsChoice', p); return false;}
      if (p.options._t_tien_cl_nt < 0)  {$.showToast('$GreaterThanAR', p); return false;}

      m.push(p.getMemvars()).val('tbl', 'T', dsave.sqlval(), 'ctcq20');
      p.grequest(gindex, 'SaveDistribute', '', m, function(p, d, run){
        if (run) {
          var pa = p.options.dirAbove, ga = pa.grid(), ra = ga._currRow||0;
          pa.valGrid(ra, 'da_pb_nt', 0, p.options._t_da_pb_nt);
		  pa.valGrid(ra, 'cl_nt', 0, p.options._t_tien_cl_nt);
          p._refresh();

        }
      }, r, time)
      return false;
      break;
    case 'delete':
      $.question($.msg.get("VoucherDelete"), $.msg.get("DeleteTitle"), p, function (q, v) {
        if (v) {
          var m = p.getMemvars();
          p.grequest(gindex, 'DeleteDistribute', '', m, function(p, d, run){
            if (run) {
              var pa = p.options.dirAbove, ga = pa.grid(), ra = ga._currRow||0;
              pa.valGrid(ra, 'da_pb_nt', 0, 0);
			   pa.valGrid(ra, 'cl_nt', 0, p.options._t_tien_cl_nt);
              p._refresh();
            }
          }, r, time)
        }
        q._close();
      });
      return false;
      break;
    default:
      break;
  }
  return true;
}
grid$m38Distribute2.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir, gindex = g.gridIndex, dt = g.data;
  switch (c){
    case 'tag':
      if (!v) p.valGrid(r, 'tt_nt', gindex, 0);
      else {
        var v1 = dt.val(r, 't_tt_nt') - dt.val(r, 'da_pb_nt'), v2 = p.options._t_tien_cl_nt;//p.options.memvars.val('tien_nt');
        p.valGrid(r, 'tt_nt', gindex, Math.min(v1, v2));
      }
      this.refreshSub();
      break;
    case 'tt_nt':
      this.refreshSub();
      break;
    default:
      break;
  }
}
grid$m38Distribute2.prototype.refreshSub = function () {
  var p = this._dir, g = p.grid(), dt = g.data, a = dt.query(['[tt_nt]'], ['SUM'], []), fi = p.field('tt_nt', 0), v = p.options.memvars.val('tien_nt'), pa = p.options.dirAbove, ga = pa.grid(), ra = ga._currRow||0;
  if (ga.data.count() == 0) {p.setSubtitle(['%s1', 0, '%s2', '_', '%s3', 0, '%s4', 0]); return;}
  if (dt.count()) {
    v -= a[0][0]; 
    p.options._t_da_pb_nt = a[0][0];
  }else {
    p.options._t_da_pb_nt = 0;
  }
  p.options._t_tien_cl_nt = v;
  p.setSubtitle(['%s1', pa.valGrid(ra, 'so_ct', 0), '%s2', $.date(pa.valGrid(ra, 'ngay_ct', 0)), '%s3', $.number(p.options._t_da_pb_nt, fi.format, true), '%s4', $.number(v, fi.format, true)]);
}

